// src/ui/hotbar.ts
function updateHotbar() {
  var slots = document.querySelectorAll("#bar .sl");
  for (var i = 0;i < 9; i++) {
    var s = slots[i];
    if (!s)
      continue;
    s.innerHTML = '<span class="sn">' + (i + 1) + "</span>";
    if (P.hb[i]) {
      var cv3 = render3DItem(P.hb[i].id);
      if (cv3) {
        var c2 = cloneCV(cv3);
        c2.style.imageRendering = "pixelated";
        s.appendChild(c2);
      }
      if (P.hb[i].q > 1) {
        var sq22 = document.createElement("span");
        sq22.className = "sq";
        sq22.textContent = "" + P.hb[i].q;
        s.appendChild(sq22);
      }
    }
    s.className = "sl" + (i === P.sel ? " on" : "");
  }
}
function buildHotbar() {
  var bar = $("bar");
  if (!bar)
    return;
  bar.innerHTML = "";
  for (var i = 0;i < 9; i++) {
    var d2 = document.createElement("div");
    d2.className = "sl" + (i === P.sel ? " on" : "");
    d2.innerHTML = '<span class="sn">' + (i + 1) + "</span>";
    d2.dataset.i = "" + i;
    d2.addEventListener("click", function() {
      P.sel = +(this.dataset.i || "0");
      updateHotbar();
    });
    bar.appendChild(d2);
  }
  updateHotbar();
}

