// src/ui/inventory-ui.ts
var invOpen2 = false;
var invCraft = new Array(4).fill(0);
function toggleInventory() {
  invOpen2 = !invOpen2;
  var el = $("inv");
  if (el)
    el.style.display = invOpen2 ? "flex" : "none";
  setInvOpen(invOpen2);
  if (invOpen2) {
    buildInvGrid();
    invCraft.fill(0);
    buildInvCraft();
    document.exitPointerLock();
  } else {
    for (var i = 0;i < 4; i++) {
      if (invCraft[i]) {
        pickUp(invCraft[i], 1);
        invCraft[i] = 0;
      }
    }
    renderer.domElement.requestPointerLock();
  }
}
function buildInvGrid() {
  var g = $("igrid");
  if (!g)
    return;
  g.innerHTML = "";
  if (P.gm === 1) {
    var ids = Object.keys(B);
    for (var i = 0;i < ids.length; i++) {
      var id = +ids[i];
      var d2 = document.createElement("div");
      d2.className = "ic";
      var cv3 = render3DItem(id);
      if (cv3) {
        var ic = cloneCV(cv3);
        ic.style.imageRendering = "pixelated";
        d2.appendChild(ic);
      }
      var nm = document.createElement("span");
      nm.className = "nm";
      nm.textContent = B[id].n;
      d2.appendChild(nm);
      d2.dataset.id = "" + id;
      d2.addEventListener("click", function() {
        var bid = +(this.dataset.id || "0");
        P.hb[P.sel] = { id: bid, q: 64 };
        updateHotbar();
        showAlert(B[bid].n);
      });
      g.appendChild(d2);
    }
  } else {
    for (var i = 0;i < 9; i++) {
      var d2 = document.createElement("div");
      d2.className = "ic";
      d2.dataset.si = "" + i;
      if (P.hb[i]) {
        var cv3 = render3DItem(P.hb[i].id);
        if (cv3) {
          var ic = cloneCV(cv3);
          ic.style.imageRendering = "pixelated";
          d2.appendChild(ic);
        }
        var nm = document.createElement("span");
        nm.className = "nm";
        nm.textContent = B[P.hb[i].id].n + " x" + P.hb[i].q;
        d2.appendChild(nm);
      }
      g.appendChild(d2);
    }
  }
}
function match2x2() {
  var g3 = [invCraft[0], invCraft[1], 0, invCraft[2], invCraft[3], 0, 0, 0, 0];
  for (var r = 0;r < RECIPES.length; r++) {
    var pat = RECIPES[r][0], match = true;
    for (var j = 0;j < 9; j++) {
      if (pat[j] !== g3[j]) {
        match = false;
        break;
      }
    }
    if (match)
      return { id: RECIPES[r][1], q: RECIPES[r][2] };
  }
  var gn = invCraft.filter(function(v) {
    return v > 0;
  });
  if (gn.length === 1) {
    for (var r = 0;r < RECIPES.length; r++) {
      var pn = RECIPES[r][0].filter(function(v) {
        return v > 0;
      });
      if (pn.length === 1 && pn[0] === gn[0])
        return { id: RECIPES[r][1], q: RECIPES[r][2] };
    }
  }
  return null;
}
function buildInvCraft() {
  var g = $("icraft");
  if (!g)
    return;
  g.innerHTML = "";
  for (var i = 0;i < 4; i++) {
    var d2 = document.createElement("div");
    d2.className = "cs";
    d2.dataset.i = "" + i;
    if (invCraft[i]) {
      var cv3 = render3DItem(invCraft[i]);
      if (cv3) {
        var ci2 = cloneCV(cv3);
        ci2.style.imageRendering = "pixelated";
        d2.appendChild(ci2);
      }
    }
    d2.addEventListener("click", function() {
      var idx = +(this.dataset.i || "0");
      if (invCraft[idx]) {
        pickUp(invCraft[idx], 1);
        invCraft[idx] = 0;
        buildInvCraft();
        updateHotbar();
        return;
      }
      var it = P.hb[P.sel];
      if (it && it.q > 0) {
        invCraft[idx] = it.id;
        it.q--;
        if (it.q <= 0)
          P.hb[P.sel] = null;
        updateHotbar();
        buildInvCraft();
      }
    });
    g.appendChild(d2);
  }
  var res = match2x2(), out = $("icout");
  if (!out)
    return;
  out.innerHTML = "";
  if (res) {
    var cv3 = render3DItem(res.id);
    if (cv3) {
      var co = cloneCV(cv3);
      co.style.imageRendering = "pixelated";
      out.appendChild(co);
    }
  }
  out.onclick = function() {
    var res2 = match2x2();
    if (!res2)
      return;
    pickUp(res2.id, res2.q);
    invCraft.fill(0);
    buildInvCraft();
    updateHotbar();
    showAlert("合成 " + B[res2.id].n + (res2.q > 1 ? " x" + res2.q : ""));
  };
}

// src/ui/crafting-ui.ts
var craftOpen2 = false;
var craftGrid = new Array(9).fill(0);
function matchRecipe() {
  for (var r = 0;r < RECIPES.length; r++) {
    var pat = RECIPES[r][0], match = true;
    for (var j = 0;j < 9; j++) {
      if (pat[j] !== craftGrid[j]) {
        match = false;
        break;
      }
    }
    if (match)
      return { id: RECIPES[r][1], q: RECIPES[r][2] };
    var pn = pat.filter(function(v) {
      return v > 0;
    });
    if (pn.length === 1) {
      var gn = craftGrid.filter(function(v) {
        return v > 0;
      });
      if (gn.length === 1 && gn[0] === pn[0])
        return { id: RECIPES[r][1], q: RECIPES[r][2] };
    }
  }
  return null;
}
function toggleCrafting() {
  craftOpen2 = !craftOpen2;
  var el = $("craft");
  if (el)
    el.style.display = craftOpen2 ? "flex" : "none";
  setCraftOpen(craftOpen2);
  if (craftOpen2) {
    craftGrid.fill(0);
    updateCraftUI();
    document.exitPointerLock();
  } else {
    for (var i = 0;i < 9; i++) {
      if (craftGrid[i]) {
        pickUp(craftGrid[i], 1);
        craftGrid[i] = 0;
      }
    }
    renderer.domElement.requestPointerLock();
  }
}
function updateCraftUI() {
  var cells = document.querySelectorAll(".cs");
  for (var i = 0;i < 9; i++) {
    var c = cells[i];
    if (!c)
      continue;
    c.innerHTML = "";
    if (craftGrid[i]) {
      var cv3 = render3DItem(craftGrid[i]);
      if (cv3) {
        var ci2 = cloneCV(cv3);
        ci2.style.imageRendering = "pixelated";
        c.appendChild(ci2);
      }
    }
  }
  var res = matchRecipe(), out = $("cout");
  if (!out)
    return;
  out.innerHTML = "";
  if (res) {
    var cv3 = render3DItem(res.id);
    if (cv3) {
      var co = cloneCV(cv3);
      co.style.imageRendering = "pixelated";
      out.appendChild(co);
    }
  }
}
function initCrafting() {
  var g = $("cgrid");
  if (!g)
    return;
  g.innerHTML = "";
  for (var i = 0;i < 9; i++) {
    var d2 = document.createElement("div");
    d2.className = "cs";
    d2.dataset.i = "" + i;
    d2.addEventListener("click", function() {
      var idx = +(this.dataset.i || "0");
      if (craftGrid[idx]) {
        pickUp(craftGrid[idx], 1);
        craftGrid[idx] = 0;
        updateCraftUI();
        return;
      }
      var it = P.hb[P.sel];
      if (it && it.q > 0) {
        craftGrid[idx] = it.id;
        it.q--;
        if (it.q <= 0)
          P.hb[P.sel] = null;
        updateHotbar();
        updateCraftUI();
      }
    });
    g.appendChild(d2);
  }
  var outEl = $("cout");
  if (outEl)
    outEl.addEventListener("click", function() {
      var res = matchRecipe();
      if (!res)
        return;
      pickUp(res.id, res.q);
      craftGrid.fill(0);
      updateCraftUI();
      updateHotbar();
      showAlert("合成 " + B[res.id].n + (res.q > 1 ? " x" + res.q : ""));
    });
}

