// src/main.ts
var { floor: fl15, min: mn11 } = Math;
setOnCraftTable(toggleCrafting);
function frameYield() {
  return new Promise(function(r) {
    requestAnimationFrame(function() {
      r();
    });
  });
}
var prevT = 0;
var fpsCount = 0;
var fpsTime = 0;
function gameLoop(t) {
  requestAnimationFrame(gameLoop);
  var dt = mn11(0.05, (t - prevT) / 1000);
  prevT = t;
  fpsCount++;
  fpsTime += dt;
  if (fpsTime >= 1) {
    setFps(fpsCount);
    fpsCount = 0;
    fpsTime = 0;
  }
  if (P.dead) {
    renderer.render(scene, camera);
    return;
  }
  updatePhysics(dt);
  updateActions(dt);
  updateMobs(dt);
  updateArrows(dt);
  updateExplosions(dt);
  updateDrops(dt);
  updateParticles(dt);
  updateDayNight(dt, P.x, P.y, P.z);
  updateWeather(dt);
  updateHungerSystem(dt);
  updateMobRespawn(dt);
  for (var mi = 0;mi < mobs.length; mi++) {
    if (mobs[mi].hpBar && mobs[mi].hpBar.sp.visible)
      mobs[mi].hpBar.sp.lookAt(camera.position);
  }
  if (fpsCount % 20 === 0)
    updateChunks(P.x, P.z);
  var ui = $("ui");
  if (ui && ui.style.display !== "none" && fpsCount % 15 === 0)
    updateDebug();
  renderer.render(scene, camera);
}
async function init() {
  var ltxt = $("ltxt"), lfill = $("lfill");
  if (ltxt)
    ltxt.textContent = "生成地形...";
  if (lfill)
    lfill.style.width = "5%";
  await frameYield();
  await frameYield();
  var spCx = fl15(WORLD_SIZE / 2 / CHUNK_SIZE), spCz = fl15(WORLD_SIZE / 2 / CHUNK_SIZE);
  var genR = RENDER_DISTANCE + 1;
  var done = 0;
  for (var dx = -genR;dx <= genR; dx++)
    for (var dz = -genR;dz <= genR; dz++) {
      if (dx * dx + dz * dz > genR * genR)
        continue;
      ensureTerrain(spCx + dx, spCz + dz);
      done++;
      if (lfill)
        lfill.style.width = 5 + done * 0.3 + "%";
      await frameYield();
    }
  if (ltxt)
    ltxt.textContent = "生成树木...";
  var treeR = RENDER_DISTANCE;
  done = 0;
  for (var dx2 = -treeR;dx2 <= treeR; dx2++)
    for (var dz2 = -treeR;dz2 <= treeR; dz2++) {
      if (dx2 * dx2 + dz2 * dz2 > treeR * treeR)
        continue;
      ensureTrees(spCx + dx2, spCz + dz2);
      done++;
      if (done % 2 === 0) {
        if (lfill)
          lfill.style.width = 35 + done * 0.3 + "%";
        await frameYield();
      }
    }
  if (ltxt)
    ltxt.textContent = "构建区块...";
  if (lfill)
    lfill.style.width = "50%";
  await frameYield();
  await buildInitialChunks(function(pct) {
    if (lfill)
      lfill.style.width = pct + "%";
  });
  if (ltxt)
    ltxt.textContent = "生成生物...";
  if (lfill)
    lfill.style.width = "92%";
  await frameYield();
  spawnInitialMobs();
  P.y = findGround(fl15(P.x), fl15(P.z)) + 2;
  P.fallY = P.y;
  buildHotbar();
  updateHP();
  updateHungerUI();
  updateXP();
  initCrafting();
  if (ltxt)
    ltxt.textContent = "完成！";
  if (lfill)
    lfill.style.width = "100%";
  await frameYield();
  var load = $("load");
  if (load)
    load.style.display = "none";
  renderer.domElement.requestPointerLock();
  requestAnimationFrame(gameLoop);
}
function startGame(mode) {
  applyGameMode(mode);
  init();
}
setupGameModeUI(startGame);
var respawnBtn = $("respawn-btn");
if (respawnBtn)
  respawnBtn.addEventListener("click", respawn);
initInput({
  onDigitKey: function(sel) {
    P.sel = sel;
    updateHotbar();
  },
  onScroll: function(dir) {
    P.sel = (P.sel + dir + 9) % 9;
    updateHotbar();
  },
  onToggleInventory: function() {
    if (craftOpen2)
      toggleCrafting();
    else
      toggleInventory();
  },
  onCloseUI: function() {
    if (craftOpen2)
      toggleCrafting();
    else if (invOpen2)
      toggleInventory();
  },
  onToggleFly: function() {
    P.fly = !P.fly;
  },
  onToggleDebug: function() {
    var el = $("ui");
    if (el)
      el.style.display = el.style.display === "none" ? "block" : "none";
  },
  onToggleView: function() {
    P.viewMode = (P.viewMode + 1) % 3;
  },
  onDropItem: function() {
    var it = P.hb[P.sel];
    if (it && it.q > 0) {
      spawnDrop(P.x, P.y + 1, P.z, it.id, 1);
      it.q--;
      if (it.q <= 0)
        P.hb[P.sel] = null;
      updateHotbar();
    }
  },
  getPlayerState: function() {
    return { ry: P.ry, rx: P.rx, dead: P.dead };
  },
  setPlayerLook: function(ry, rx) {
    P.ry = ry;
    P.rx = rx;
  },
  isInvOrCraftOpen: function() {
    return invOpen2 || craftOpen2;
  }
});
window.addEventListener("resize", function() {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
